SELECT CASE WHEN c.city IN ('Bangkok', 'Chiang Mai') THEN 'core' ELSE 'other' END AS city_group, COUNT(DISTINCT o.shipping_fee) AS unique_statuss FROM orders o LEFT JOIN customers c ON o.customer_id = c.id INNER JOIN stores s ON o.store_id = s.id WHERE s.store_name LIKE '%Expre%' GROUP BY CASE WHEN c.city IN ('Bangkok', 'Chiang Mai') THEN 'core' ELSE 'other' END ORDER BY city_group LIMIT 10;
